#!/usr/bin/env python3
# luxarch:targeted-guard-run hook v5 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Deny a full luxarch scan piped into a filter: check one rule or one file with `--rule`.

`luxarch --rule <id>` runs only the matching rules, and `--path <file>` narrows the output to one
file. A full scan (`make arch`, or the image with no `--rule`) takes minutes on a large repo, and
filtering its output with grep, head or tail to read one rule or one file spends all of that to
throw most of it away. The whole repo's per-rule counts are in `.luxarch-status.json`
(`make status`).

PreToolUse(Bash): deny a pipeline with a stage whose output holds a full luxarch scan's and a later
stage that is a text filter (`grep`, `awk` and its kin, `head`, `tail`, `jq`, `read`, `python -c`
reading stdin, a group whose first command is one, ...). Every text the call runs is judged: a
`bash -c` body, a shell behind a wrapper, `eval`, a heredoc fed to a shell, a `$( … )`.

A stage's output holds a scan's when it runs one; when a group in it does (`{ …; }`, `( … )`,
`$( … )` quoted or not, `if … fi`, `for|while|until … done`, `case … esac`, a reserved word in a
case pattern closing nothing); when a function it calls does, its positional parameters read
from the call; when the shell text it runs does; or when it expands a variable assigned a scan's
output. Its command is read past assignments and wrappers as `_guard_cmd._unwrapped` reads them
(`nice -n 19`, `timeout -s KILL 900`, `stdbuf -oL`, `ionice -c3`, `time -p`, `env`) and past
`sudo`, `xargs`, `busybox` and `builtin`. make runs a scan when any goal is `arch` and no option,
in a cluster too (`-sn`), makes it a dry run; `-Capp` and `-j8 -Oline` are values, not dry runs.

Words are expanded from the text's own assignments and from the literal lists of the loops around
them (each item in turn; `set -- $item` sets the positional parameters; `${x#p}`, `${x%%p}` trim).
A full scan run on its own or saved to a file, `make status`, a `--rule` run, the image's non-scan
modes (`--doc`, `--emit`, `--sweep`, `--plan`, `--changelog`, an unambiguous prefix of one, or a
mode argparse rejects) and a make dry run all pass. A literal mode or `--rule` decides before an
unread word elsewhere can: `--emit $name` is no scan. In a `docker run` of a luxarch image, the
container's command decides, not the image's name (`_guard_cmd.guard_runs`): `python -m pytest` in
an image tagged `luxarch:…` is not a scan, and `python -c "…main()"` with
`sys.argv = ['luxarch', '--rule', 'x']` is a targeted one. A container's own shell text is judged
command by command as if typed in it (a loop by its inner commands; a program a variable chooses,
as guard-cmd reads one, is a full scan). An image whose name stays unread is luxarch's only when
the container's command names luxarch. `--rule` is read as the CLI reads it
(`_guard_cmd.selects_rules`): a value with no token left after splitting on commas, or one that is
a variable the hook cannot read, runs every rule. A tool call whose event cannot be read is
denied.
"""

from __future__ import annotations

import fnmatch
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import (  # sibling helper, loaded by path
    _SHELLS,
    SimpleCommand,
    _lex,
    _matching_paren,
    _runs_arg,
    _substitutions,
    argv_bodies,
    command_text,
    executable_texts,
    expand,
    guarded,
    load_event,
    shell_split,
    simple_commands,
    text_field,
    tool_input,
)
from _guard_cmd import (  # sibling helper, loaded by path
    _decides,
    _unwrapped,
    guard_runs,
    selects_rules,
)

# The luxarch image, by registry ref, local tag or digest, or the variable that names it.
_IMAGE = re.compile(
    r"^(?:[\w.:${}-]+/)*luxarch(?::[\w.${}-]+)?(?:@sha256:\w+)?$"
    r"|^\$\{?LUXARCH(?:_IMAGE)?\}?$|^\$\(LUXARCH(?:_IMAGE)?\)$"
)
# `docker run` options that take no value; every other option takes the next word unless it is
# written `--opt=value`.
_FLAG_ONLY = {
    "--rm",
    "-i",
    "-t",
    "-it",
    "-ti",
    "-d",
    "--detach",
    "--init",
    "--privileged",
    "--read-only",
    "--interactive",
    "--tty",
    "-q",
    "--quiet",
    "--sig-proxy",
    "-P",
    "--publish-all",
    "--no-healthcheck",
    "--oom-kill-disable",
    "--disable-content-trust",
}
# Image arguments that make a run targeted, or not a scan at all.
_NOT_A_FULL_SCAN = {
    "--sweep",
    "--plan",
    "--emit",
    "--doc",
    "--docs",
    "--playbook",
    "--list-rules",
    "--fleet-versions",
    "--fleet-deps",
    "--changelog",
    "--new-rules",
    "--upgrade",
    "--version",
    "--help",
    "-h",
    "--map",
    # modes some releases had, and argparse rejects in the others: no scan runs either way
    "--list-docs",
    "--list-playbooks",
    "--list-emits",
    "--list-sweeps",
    "--explain",
    "--rules",
    "--playbooks",
}
# the CLI's options a full scan takes: a prefix of one of them is not read as a mode
_SCAN_OPTIONS = {
    "--repo", "--config", "--kind", "--target", "--rule", "--path", "--jobs", "--json",
    "--quiet", "--full", "--only", "--ops", "--verdict", "--assert-scans", "--since",
    "--update", "--error-unmatch",
}  # fmt: skip
# make options that take a value (the rest of the word, else the next word), and those that run
# nothing. A short-option cluster is read letter by letter: `-Capp` is `-C app`, `-j8 -Oline` sets
# jobs and output sync, `-sn` is a dry run.
_MAKE_VALUED = {
    "--directory",
    "--file",
    "--makefile",
    "--include-dir",
    "--old-file",
    "--what-if",
    "--new-file",
    "--assume-old",
    "--assume-new",
    "--eval",
}
_MAKE_VALUE_LETTERS = set("CfIoW")
# `-j`, `-l` and `-O` take a value only attached, but `-j`/`-l` also take a number after them.
_MAKE_OPTIONAL_LETTERS = set("jlO")
_MAKE_NUMBERED = {"--jobs", "--load-average", "--max-load"}
_MAKE_NUMBER = re.compile(r"^\d+(?:\.\d+)?$")
_MAKE_DRY_LETTERS = set("nqpt")
_MAKE_DRY = {
    "--dry-run",
    "--just-print",
    "--recon",
    "--question",
    "--print-data-base",
    "--touch",
}
# Leaders `_guard_cmd._unwrapped` does not set aside, with their options that take the next word.
_LEADERS = {
    "sudo": {"-u", "-g", "-C", "-D", "-h", "-p", "-r", "-t", "-U"},
    "doas": {"-u", "-C"},
    "builtin": set(),
    "busybox": set(),
    "xargs": {"-I", "-L", "-n", "-P", "-s", "-d", "-E", "-a"},
}
_FILTERS = {
    "grep",
    "egrep",
    "fgrep",
    "zgrep",
    "ugrep",
    "rg",
    "ag",
    "ack",
    "awk",
    "gawk",
    "mawk",
    "nawk",
    "sed",
    "perl",
    "head",
    "tail",
    "jq",
    "cut",
    "wc",
    "sort",
    "uniq",
    "less",
    "more",
    # the shell reading the output line by line: `| while read l; do …`
    "read",
    "mapfile",
    "readarray",
}
_PYTHON = re.compile(r"^python(?:\d+(?:\.\d+)?)?$")
# `python -c` code that reads what is piped to it
_READS_STDIN = re.compile(r"stdin|fileinput|\binput\(|\bopen\(\s*0\s*[,)]|/dev/stdin")
# Where a statement ends and where a pipe joins two stages, matched in the mask; only those at the
# top level count, never one inside a group (`{ …; }`, `( … )`, `$( … )`, `if … fi`,
# `for|while|until … done`, `case … esac`).
_STATEMENT = re.compile(r"&&|\|\||;|\n|(?<![>&<0-9|])&(?![>&])")
_PIPE = re.compile(r"(?<!>)\|&?")
# A redirection word (`2>&1`, `>out`, `> out`): the shell's, not the container command's.
_REDIRECTION = re.compile(r"^(?:\d+|&)?(?:>>?|<|>&|<&|>\|)(.*)$", re.S)
# A newline that continues the command: after a backslash, or after a pipe, `&&` or `||`.
_CONTINUED = re.compile(r"\\\n|(?<=\|)[ \t]*\n|(?<=&&)[ \t]*\n")
# Reserved words a command can follow: `if make arch | tail; then …`, `then …`, `do …`.
_KEYWORDS = {"if", "then", "elif", "else", "do", "while", "until", "!"}
# Words after which the next word is still a command word.
_CMDPOS_WORDS = _KEYWORDS | {"time"}
# Reserved words that open and close a compound command, read at a command word only.
_OPENERS = {"if", "for", "while", "until", "case", "select"}
_CLOSERS = {"fi", "done", "esac"}
# The word that ends a command word in the mask.
_WORD_END = set(" \t\n;&|()<>")
_CMD_START = set(";&|\n")
# The words after `for`/`select` up to `do` (its variable and list), and after `case` up to `in`:
# not commands.
_LOOP_HEADER = re.compile(
    r"\s+[A-Za-z_]\w*(?:\s+in\b[^;\n]*)?\s*[;\n]|\s*\(\(.*?\)\)\s*[;\n]?", re.S
)
_CASE_HEADER = re.compile(r"\s+(?:\S+\s+)?in(?=[\s;]|$)")
# `for <var> in <list>`: the list is read from the raw text.
_LOOP = re.compile(
    r"(?:^|(?<=[\s;&|(]))(?:for|select)\s+([A-Za-z_]\w*)\s+in(?=\s)([^;\n]*)"
)
_LOOP_VARIANTS = 32
# A function definition: `f() {`, `f() (`, `function f {`, `function f() {`.
_FUNCTION = re.compile(
    r"(?:^|(?<=[\s;&|(]))(?:function\s+([\w.:-]+)\s*(?:\(\s*\))?|([A-Za-z_][\w.:-]*)\s*\(\s*\))"
    r"\s*[{(]"
)
_UNREAD = re.compile(r"[$`]")
# `set -- $p`: the positional parameters are a loop variable's words
_SET_FROM = re.compile(r"\bset\s+--\s+\"?\$\{?([A-Za-z_]\w*)\}?\"?")
# a word that names the guard's program or module: `luxarch`, `/usr/bin/luxarch`, `luxarch.cli`
_NAMES_LUXARCH = re.compile(r"^(?:.*/)?luxarch(?:\.[\w.]+)?$")
# a word a function call hands on unchanged: no space, quote or glob for the shell to touch
_PLAIN_WORD = re.compile(r"[\w./:=@%+,${}#-]*")
# Programs that run no other program: an unread word in their arguments starts no scan
_RUNS_NOTHING = {
    "git", "diff", "cmp", "stat", "du", "df", "tree", "realpath", "readlink", "basename",
    "dirname", "date", "sleep", "touch", "mkdir", "cp", "mv", "rm", "chmod", "ln", "tr", "tee",
    "column", "tac", "file", "md5sum", "sha256sum",
}  # fmt: skip
# `NAME=$(…)` / `NAME="$(…)"`, read in the raw text where the mask shows the name is code
_SCAN_ASSIGNMENT = re.compile(r"(?:^|(?<=[\s;&|(]))([A-Za-z_]\w*)=\"?(?=\$\()")
# `watch` runs its arguments, joined, through `sh -c`.
_WATCH_VALUED = {"-n", "--interval"}
_MAX_NESTING = 6


class _TooDeep(Exception):
    """Shells, groups or functions nest deeper than the hook reads."""


def _flat_substitutions(raw: str) -> str:
    """`raw` with each `$( … )` and backtick substitution outside single quotes replaced by one
    unread word, so the words around it split as the shell splits them."""
    out: list[str] = []
    i, quote, n = 0, "", len(raw)
    while i < n:
        c = raw[i]
        if quote == "'":
            quote = "" if c == "'" else quote
            out.append(c)
            i += 1
        elif c == "\\" and i + 1 < n:
            out.append(raw[i : i + 2])
            i += 2
        elif c == "'" and not quote:
            quote = "'"
            out.append(c)
            i += 1
        elif c == '"':
            quote = "" if quote == '"' else '"'
            out.append(c)
            i += 1
        elif raw.startswith("$(", i):
            out.append("$__SUBSTITUTION__")
            i = _matching_paren(raw, i + 1) + 1
        elif c == "`":
            end = raw.find("`", i + 1)
            out.append("$__SUBSTITUTION__")
            i = n if end < 0 else end + 1
        else:
            out.append(c)
            i += 1
    return "".join(out)


def _words(raw: str, values: dict[str, str] | None = None) -> list[str]:
    raw = _flat_substitutions(raw)
    try:
        words = shell_split(raw)  # linear on a long word, where shlex is quadratic
    except ValueError:
        words = raw.split()
    return [expand(w, values) for w in words] if values else words


def _command(words: list[str]) -> list[str]:
    """``words`` from the command word on: a group's `(`/`{`, reserved words, assignments and
    wrappers set aside (guard-cmd's own, so `nice -n 19`, `timeout -s KILL 900`, `stdbuf -oL`,
    `ionice -c3`, `time -p` and `env -i` read as they run, then `sudo`, `xargs`, `busybox` and the
    other leaders here)."""
    words = list(words)
    while words:
        word = words[0]
        first = word.lstrip("({")
        if word[:1] == "(":
            first = first.rstrip(")")  # `(head)`: a one-word subshell
        if not first or first in _KEYWORDS:
            words = words[1:]
            continue
        first = first.rstrip(";")  # `{ tail; }`
        if first == "command" and words[1:2] in (["-v"], ["-V"]):
            return []  # `command -v luxarch` looks the program up, runs nothing
        words = _unwrapped([first, *words[1:]])
        if not words:
            return []
        if words[0][:1] in "({" or words[0] in _KEYWORDS:  # `time { …`, `time ! …`
            continue
        if Path(words[0]).name not in _LEADERS:
            return words
        valued = _LEADERS[Path(words[0]).name]
        i = 1
        while i < len(words) and words[i].startswith("-"):
            i += 2 if words[i] in valued else 1
        words = words[i:]
    return []


def _depths(masked: str) -> tuple[list[int], list[tuple[int, int]]]:
    """The group depth of each character of `masked`, and the spans of its `case` patterns.

    A group is a `( … )` (a subshell or a substitution), a `{ … }` whose braces are command words,
    and a compound command from its opening reserved word to its closing one (`if … fi`,
    `for|while|until|select … done`, `case <word> in … esac`). Its opener and closer sit at the
    outer depth. A loop's header (`for x in a b;`) and a `case` subject are inside it. They and a
    `case` pattern (`x)`, `(x)`,
    `done|fi)`) are no command, so they are returned as spans to blank, and a reserved word in
    them closes nothing. A `{a,b}`, a `${x}` and a
    reserved word that is an argument (`echo done`) do not nest."""
    n = len(masked)
    out = [0] * n
    patterns: list[tuple[int, int]] = []
    # (kind, command position to restore after the closer); kind "case-pattern" expects a pattern
    stack: list[tuple[str, bool]] = []
    cmdpos, after_function = True, False
    i = 0
    while i < n:
        c = masked[i]
        depth = len(stack)
        if stack and stack[-1][0] == "case-pattern" and not c.isspace():
            m = re.match(r"esac(?=[\s;&|)]|$)", masked[i:])
            if m:
                stack.pop()
                out[i : i + 4] = [len(stack)] * 4
                cmdpos = False
                i += 4
                continue
            close = masked.find(")", i + (1 if c == "(" else 0))
            close = n - 1 if close < 0 else close
            out[i : close + 1] = [depth] * (close + 1 - i)
            patterns.append((i, close + 1))
            stack[-1] = ("case", False)
            cmdpos = True
            i = close + 1
            continue
        if c.isspace():
            out[i] = depth
            if c == "\n":
                cmdpos = True
            i += 1
            continue
        if c in _CMD_START:
            out[i] = depth
            cmdpos = True
            if stack and stack[-1][0] == "case" and masked.startswith((";;", ";&"), i):
                end = i + (3 if masked.startswith(";;&", i) else 2)
                out[i:end] = [depth] * (end - i)
                stack[-1] = ("case-pattern", False)
                i = end
                continue
            i += 1
            continue
        if c == "(":
            out[i] = depth
            substitution = i > 0 and masked[i - 1] in "$<>"
            stack.append(("subst" if substitution else "paren", cmdpos))
            cmdpos = True
            i += 1
            continue
        if c == ")":
            if stack:
                kind, before = stack.pop()
                out[i] = len(stack)
                cmdpos = before if kind == "subst" else True
            else:
                out[i] = 0
            i += 1
            continue
        j = i
        while j < n and masked[j] not in _WORD_END:
            j += 1
        if j == i:  # `<` or `>`
            out[i] = depth
            i += 1
            continue
        word = masked[i:j]
        if cmdpos and word == "{":
            out[i] = depth
            stack.append(("brace", True))
        elif cmdpos and word == "}" and stack and stack[-1][0] == "brace":
            stack.pop()
            out[i] = len(stack)
            cmdpos = False
        elif cmdpos and word in _OPENERS:
            header = (
                _CASE_HEADER.match(masked, j)
                if word == "case"
                else _LOOP_HEADER.match(masked, j)
                if word in ("for", "select")
                else None
            )
            out[i:j] = [depth] * (j - i)
            if header:  # inside the group, and no command: blanked like a pattern
                out[j : header.end()] = [depth + 1] * (header.end() - j)
                patterns.append((j, header.end()))
                j = header.end()
            stack.append(("case-pattern" if word == "case" else "kw", False))
            cmdpos = True
        elif cmdpos and word in _CLOSERS and stack and stack[-1][0] in ("kw", "case"):
            stack.pop()
            out[i:j] = [len(stack)] * (j - i)
            cmdpos = False
        else:
            out[i:j] = [depth] * (j - i)
            if after_function:
                after_function = False  # the function's name: its `{` or `()` follows
            elif word == "function" and cmdpos:
                after_function = True
            elif not (cmdpos and (word in _CMDPOS_WORDS or re.match(r"^\w+=", word))):
                cmdpos = False
        i = j
    return out, patterns


def _make_runs_arch(args: list[str]) -> bool:
    """make with these arguments runs the `arch` goal: one of its goals is `arch` and no option
    makes it a dry run."""
    goals: list[str] = []
    i = 0
    while i < len(args):
        a = args[i]
        i += 1
        if a == "--":
            goals.extend(args[i:])
            break
        if a.startswith("--"):
            name = a.split("=", 1)[0]
            if name in _MAKE_DRY:
                return False
            if "=" not in a and name in _MAKE_VALUED:
                i += 1
            elif "=" not in a and name in _MAKE_NUMBERED:
                i += 1 if i < len(args) and _MAKE_NUMBER.match(args[i]) else 0
            continue
        if a.startswith("-") and len(a) > 1:
            for k, ch in enumerate(a[1:], 1):
                last = k == len(a) - 1
                if ch in _MAKE_DRY_LETTERS:
                    return False
                if ch in _MAKE_VALUE_LETTERS:
                    i += 1 if last else 0  # the next word, else the rest of this one
                    break
                if ch in _MAKE_OPTIONAL_LETTERS:
                    numbered = i < len(args) and _MAKE_NUMBER.match(args[i])
                    i += 1 if last and ch in "jl" and numbered else 0
                    break
            continue
        if "=" not in a:
            goals.append(a)
    return any(g.rstrip(");}") == "arch" for g in goals)


def _without_redirections(words: list[str]) -> list[str]:
    out: list[str] = []
    skip = False
    for w in words:
        if skip:
            skip = False  # the target of a `>` written apart from it
            continue
        m = _REDIRECTION.match(w)
        if m:
            skip = not m.group(1)
            continue
        out.append(w)
    return out


def _luxarch_container(args: list[str]) -> list[str] | None:
    """What a `docker run` of a luxarch image runs (an `--entrypoint` override first), or None for
    another image or another docker command. An image whose name the hook cannot read is luxarch's
    only when the container's command names luxarch (`"$IMG" python -m luxarch`)."""
    if args[:1] == ["container"]:
        args = args[1:]
    if args[:1] != ["run"]:
        return None
    entrypoint: list[str] = []
    i = 1
    while i < len(args):
        a = args[i]
        if a == "--entrypoint" or a.startswith("--entrypoint="):
            value = (
                a.split("=", 1)[1]
                if "=" in a
                else (args[i + 1] if i + 1 < len(args) else "")
            )
            entrypoint = [value] if value else []
        if not a.startswith("-"):
            command = [*entrypoint, *_without_redirections(args[i + 1 :])]
            if _IMAGE.match(a):
                return command
            name = re.split(r"[:@]", a.rsplit("/", 1)[-1], maxsplit=1)[0]
            if _UNREAD.search(name) and any(_NAMES_LUXARCH.match(w) for w in command):
                return command
            return None
        flag_only = a in _FLAG_ONLY or re.fullmatch(r"-[dit]+", a) is not None
        i += 1 if (flag_only or "=" in a) else 2
    return None


def _targeted(command: list[str]) -> bool:
    """A literal word of `command` picks a mode that is no full scan (`--doc`, `--emit`, `--sweep`,
    `--version`, …) or a literal `--rule`, whatever value an unread word after it holds."""
    return selects_rules(command) or any(
        not _UNREAD.search(w) and _is_mode(w.split("=", 1)[0]) for w in command
    )


def _is_mode(flag: str) -> bool:
    """`flag` is a non-scan mode, or a prefix argparse resolves only to modes (`--list` for
    `--list-rules`): no scan option shares it."""
    if flag in _NOT_A_FULL_SCAN:
        return True
    if len(flag) < 5 or not flag.startswith("--"):
        return False
    return any(m.startswith(flag) for m in _NOT_A_FULL_SCAN) and not any(
        o.startswith(flag) for o in _SCAN_OPTIONS
    )


def _scans_all(run: list[str]) -> bool:
    """luxarch run with these arguments runs every rule."""
    flags = {r.split("=", 1)[0] for r in run if r.startswith("-")}
    return not selects_rules(run) and not flags & _NOT_A_FULL_SCAN


def _container_shell_scans(command: list[str], depth: int) -> bool | None:
    """For a container command that is a shell running a text (`sh -c '…'`): whether that text
    writes a full scan's output, each command of it judged as typed in the container (a loop or
    group by its inner commands). None for any other command."""
    words = _command(command)
    if not words or Path(words[0]).name not in _SHELLS:
        return None
    bodies = argv_bodies(SimpleCommand((), tuple(words), ""))
    if not bodies:
        return None
    if any(
        _decides(k, v)
        for body in bodies
        for sc in simple_commands(body)
        for k, v in sc.env
    ):
        return True  # `PATH=$P pytest`: a variable chooses the program (guard-cmd's contract)
    return any(_Text(body, True, depth + 1).emits_any() for body in bodies)


def _full_scan(words: list[str], inside: bool, depth: int = 0) -> bool:
    """The command `words` (wrappers set aside) runs a full scan itself."""
    if not words:
        return False
    head = Path(words[0]).name
    if head == "make":
        return _make_runs_arch(words[1:])
    if head == "luxarch":  # the guard's own command, inside a container's shell
        return _scans_all(words[1:])
    if inside and head in _RUNS_NOTHING:
        return False
    if inside and head not in {"docker", "podman"}:
        # inside a luxarch container every program is read as guard-cmd reads the container's
        # command: `python -m luxarch`, `nice luxarch`, a program named by a variable
        shell = _container_shell_scans(words, depth)
        if shell is not None:
            return shell
        return not _targeted(words) and any(
            _scans_all(run) for run in guard_runs("luxarch", words)
        )
    if head in {"docker", "podman"}:
        command = _luxarch_container(words[1:])
        if command is None or _targeted(command):
            return False
        shell = _container_shell_scans(command, depth)
        if shell is not None:
            return shell
        return any(_scans_all(run) for run in guard_runs("luxarch", command))
    return False


def _is_filter(words: list[str]) -> bool:
    if not words:
        return False
    head = Path(words[0]).name
    if head in _FILTERS:
        return True
    if _PYTHON.match(head):  # `python3 -c '…sys.stdin…'`, `python3 -Ic …`
        for k, w in enumerate(words[1:], 1):
            if not w.startswith("-") or w.startswith("--"):
                continue
            at = w.find("c", 1)
            if at > 0:
                code = w[at + 1 :] or (words[k + 1] if k + 1 < len(words) else "")
                return bool(_READS_STDIN.search(code))
    return False


def _shell_bodies(words: list[str], raw: str) -> list[tuple[str, bool]]:
    """Shell text the command `words` runs, and whether a luxarch container runs it: `sh -c`,
    `eval`, `su -c`, `find -exec`, `watch`, and a luxarch container's own shell."""
    if not words:
        return []
    out = [(b, False) for b in argv_bodies(SimpleCommand((), tuple(words), raw))]
    head = Path(words[0]).name
    if head == "watch":
        i = 1
        while i < len(words) and words[i].startswith("-"):
            i += 2 if words[i] in _WATCH_VALUED else 1
        if i < len(words):
            out.append((" ".join(words[i:]), False))
    if head in {"docker", "podman"}:
        command = _luxarch_container(words[1:])
        inner = _command(command) if command else []
        if inner:
            out.extend(
                (b, True) for b in argv_bodies(SimpleCommand((), tuple(inner), ""))
            )
    return out


def _blank(text: str, spans: list[tuple[int, int]]) -> str:
    chars = list(text)
    for a, b in spans:
        for k in range(a, b):
            if chars[k] != "\n":
                chars[k] = " "
    return "".join(chars)


def _with_args(raw: str, args: tuple[str, ...]) -> str:
    """`raw` with a function's positional parameters replaced by the words it was called with."""
    joined = " ".join(a for a in args if _PLAIN_WORD.fullmatch(a))
    if all(_PLAIN_WORD.fullmatch(a) for a in args):
        for spelling in ('"$@"', '"${@}"', '"$*"', "${@}", "$@", "$*"):
            raw = raw.replace(spelling, joined)

    def positional(m: re.Match[str]) -> str:
        n = int(m.group(1) or m.group(2))
        value = args[n - 1] if 0 < n <= len(args) else ""
        return value if _PLAIN_WORD.fullmatch(value) else m.group(0)

    return re.sub(r"\$\{(\d+)\}|\$(\d)", positional, raw)


def _with_loop_value(raw: str, var: str, item: str) -> str:
    """`raw` with the loop variable `var` replaced by `item`, its `${var#p}`, `${var##p}`,
    `${var%p}` and `${var%%p}` trims included (the shortest or longest match of the glob `p`)."""

    def trim(m: re.Match[str]) -> str:
        op, pat = m.group(1), m.group(2)
        cuts = range(len(item) + 1)
        if op[0] == "#":  # a matching prefix, shortest (`#`) or longest (`##`) first
            order = reversed(cuts) if op == "##" else cuts
            k = next((k for k in order if fnmatch.fnmatchcase(item[:k], pat)), 0)
            return item[k:]
        order = cuts if op == "%%" else reversed(cuts)  # a matching suffix
        k = next((k for k in order if fnmatch.fnmatchcase(item[k:], pat)), len(item))
        return item[:k]

    raw = re.sub(rf"\$\{{{var}(#{{1,2}}|%{{1,2}})([^}}]*)\}}", trim, raw)
    return re.sub(rf"\$\{{{var}\}}|\${var}(?!\w)", lambda _m: item, raw)


class _Text:
    """One command text, read once: its mask, group depths, functions, loops and known values.
    `loops` and `values` are the enclosing texts' (a `$( … )` inside a loop reads its variable)."""

    def __init__(
        self,
        text: str,
        inside: bool,
        depth: int,
        loops: dict[str, list[str]] | None = None,
        values: dict[str, str] | None = None,
    ) -> None:
        if depth > _MAX_NESTING:
            raise _TooDeep
        self.inside, self.depth = inside, depth
        self.raw = _CONTINUED.sub(lambda m: " " * len(m.group(0)), text)
        masked = command_text(self.raw)
        self.depths, patterns = _depths(masked)
        # `for x in a b c`: x takes each literal value (a list with an unread word is not read)
        self.loops: dict[str, list[str]] = dict(loops or {})
        self.loops.update(_loops(masked, self.raw))
        # a `case` pattern is no command: blanked, so `a|b)` splits no pipeline
        self.masked = _blank(masked, patterns)
        self.words_raw = _blank(self.raw, patterns)
        # NAME=value assignments the text makes: `L=<image>; docker run "$L"`
        self.values = dict(values or {})
        self.values.update(
            (k, v) for sc in simple_commands(self.raw) for k, v in sc.env
        )
        self.functions: dict[str, tuple[int, int]] = {}
        self.definitions: set[int] = set()  # where each function definition starts
        for m in _FUNCTION.finditer(self.masked):
            opener = m.end() - 1
            body = self._groups(opener, len(self.masked))
            if body and body[0][0] == opener + 1:
                self.functions[m.group(1) or m.group(2)] = body[0]
                self.definitions.add(m.start())
        self.heredocs = _lex(self.raw).heredocs
        self._scan_vars: set[str] | None = None
        set_from = _SET_FROM.search(self.raw)
        self.set_from = set_from.group(1) if set_from else ""

    def _child(self, text: str, in_container: bool = False) -> _Text:
        return _Text(
            text, self.inside or in_container, self.depth + 1, self.loops, self.values
        )

    def scan_vars(self) -> set[str]:
        """Variables assigned a full scan's output: `out=$(make arch 2>&1)`."""
        if self._scan_vars is None:
            self._scan_vars = set()
            for m in _SCAN_ASSIGNMENT.finditer(self.raw):
                if self.masked[m.start(1)] != self.raw[m.start(1)]:
                    continue  # inside quoted data or a comment
                found = _substitutions(self.raw[m.end() :])
                if found and self._child(found[0]).emits_any():
                    self._scan_vars.add(m.group(1))
        return self._scan_vars

    def _split(self, sep: re.Pattern[str], a: int, b: int) -> list[tuple[int, int]]:
        """The spans of `[a, b)` between the top-level matches of `sep`."""
        top = self.depths[a] if a < len(self.depths) else 0
        spans: list[tuple[int, int]] = []
        start = a
        for m in sep.finditer(self.masked, a, b):
            if self.depths[m.start()] == top:
                spans.append((start, m.start()))
                start = m.end()
        spans.append((start, b))
        return spans

    def _groups(self, a: int, b: int) -> list[tuple[int, int]]:
        """The interiors of the groups opened at the top level of `[a, b)`."""
        d = self.depths
        top = d[a] if a < b else 0
        out: list[tuple[int, int]] = []
        i = a
        while i < b:
            if d[i] == top and i + 1 < len(d) and d[i + 1] > top:
                j = i + 1
                while j < b and d[j] > top:
                    j += 1
                out.append((i + 1, j))
                i = j
            i += 1
        return out

    def _stages(self, a: int, b: int) -> list[list[tuple[int, int]]]:
        """The pipelines of `[a, b)`, each a list of its stages (a blanked stage dropped)."""
        return [
            [s for s in self._split(_PIPE, sa, sb) if self.masked[s[0] : s[1]].strip()]
            for sa, sb in self._split(_STATEMENT, a, b)
        ]

    def _variants(
        self, a: int, b: int, args: tuple[str, ...] | None
    ) -> list[list[str]]:
        """The command of the stage `[a, b)`, once per value of each loop variable it reads, with
        the calling function's arguments in place of its positional parameters."""
        raw = self.words_raw[a:b]
        if args is not None:
            raw = _with_args(raw, args)
        texts = [raw]
        if args is None and self.set_from in self.loops and re.search(r"\$\{?\d", raw):
            # `for p in "a b" "c d"; do set -- $p; … $1 $2`: the positional parameters
            texts = [
                _with_args(raw, tuple(item.split()))
                for item in self.loops[self.set_from]
            ][:_LOOP_VARIANTS]
        for name, value in self.values.items():
            # `rule="${R%%:*}"` inside `for R in …`: the assignment reads the loop variable
            if any(re.search(rf"\$\{{?{v}\b", value) for v in self.loops) and re.search(
                rf"\$\{{?{name}\b", raw
            ):
                texts = [
                    re.sub(
                        rf"\$\{{{name}\}}|\${name}(?!\w)",
                        value.replace("\\", "\\\\"),
                        t,
                    )
                    for t in texts
                ]
        for var in [
            v for v in self.loops if any(re.search(rf"\$\{{?{v}\b", t) for t in texts)
        ]:
            texts = [
                _with_loop_value(t, var, item)
                for t in texts
                for item in self.loops[var]
            ][:_LOOP_VARIANTS]
        return [_command(_words(t, self.values)) for t in texts]

    def _start(self, a: int, b: int) -> int:
        m = re.match(r"\s*", self.masked[a:b])
        return a + (m.end() if m else 0)

    def _defines(self, a: int, b: int) -> bool:
        """The stage `[a, b)` defines a function: its body runs where it is called."""
        return self._start(a, b) in self.definitions

    def _compound(self, a: int, b: int) -> bool:
        """The stage `[a, b)` is a group, a compound command or a function definition: what it
        runs is its inner commands, never its words read as one command."""
        k = self._start(a, b)
        word = re.match(r"[^\s;&|()<>]*", self.masked[k:b])
        first = word.group(0) if word else ""
        return (
            self.masked[k : k + 1] in ("(", "{")
            or first in _OPENERS
            or k in self.definitions
        )

    def _inner(self, a: int, b: int) -> list[tuple[int, int]]:
        """The stages of every group at the top level of `[a, b)`."""
        return [
            stage
            for ga, gb in self._groups(a, b)
            for pipeline in self._stages(ga, gb)
            for stage in pipeline
        ]

    def _called(
        self, variants: list[list[str]], seen: frozenset[str]
    ) -> list[tuple[str, tuple[str, ...]]]:
        """The functions of this text the stage calls, with the words of each call."""
        return [
            (words[0], tuple(_without_redirections(words[1:])))
            for words in variants
            if words and words[0] in self.functions and words[0] not in seen
        ]

    def emits(
        self,
        a: int,
        b: int,
        seen: frozenset[str] = frozenset(),
        args: tuple[str, ...] | None = None,
    ) -> bool:
        """The output of the stage `[a, b)` holds a full scan's: the stage runs one; or a group in
        it, the function it calls, a `$( … )` in it (quoted too), or the shell text it runs
        (`bash -c`, `eval`, a heredoc fed to a shell) does; or it expands a variable assigned a
        scan's output. A function definition emits nothing: its body runs where it is called."""
        if self._defines(a, b):
            return False
        variants = [] if self._compound(a, b) else self._variants(a, b, args)
        if any(_full_scan(words, self.inside, self.depth) for words in variants):
            return True
        raw = self.words_raw[a:b]
        if "$" in raw and any(
            re.search(rf"\$\{{?{v}\b", raw) for v in self.scan_vars()
        ):
            return True  # `echo "$out"` of a variable holding a scan's output
        if any(self.emits(sa, sb, seen, args) for sa, sb in self._inner(a, b)):
            return True
        for name, call_args in self._called(variants, seen):
            fa, fb = self.functions[name]
            if any(
                self.emits(sa, sb, seen | {name}, call_args)
                for pipeline in self._stages(fa, fb)
                for sa, sb in pipeline
            ):
                return True
        bodies: list[tuple[str, bool]] = [
            (s, False) for s in _substitutions(self.raw[a:b])
        ]
        for words in variants:
            bodies.extend(_shell_bodies(words, self.raw[a:b]))
            if (
                words
                and Path(words[0]).name in _SHELLS
                and not _runs_arg(tuple(words))[0]
            ):
                bodies.extend(
                    (self.raw[h.body_start : h.body_end], False)
                    for h in self.heredocs
                    if a <= h.marker < b
                )
        return any(self._child(body, in_c).emits_any() for body, in_c in bodies)

    def emits_any(self) -> bool:
        """Running the whole text writes a full scan's output."""
        return any(
            self.emits(sa, sb)
            for pipeline in self._stages(0, len(self.masked))
            for sa, sb in pipeline
        )

    def filters(self, a: int, b: int, args: tuple[str, ...] | None = None) -> bool:
        """The stage `[a, b)` reads its input as a text filter: it is one, or the first command
        of its group is (`| { tail; }`, `| (head)`, `| while read l; do …`)."""
        if any(_is_filter(words) for words in self._variants(a, b, args)):
            return True
        return any(
            self.filters(*pipeline[0], args)
            for ga, gb in self._groups(a, b)[:1]
            for pipeline in self._stages(ga, gb)[:1]
            if pipeline
        )

    def filtered(
        self,
        a: int,
        b: int,
        seen: frozenset[str] = frozenset(),
        args: tuple[str, ...] | None = None,
    ) -> bool:
        """A pipeline in `[a, b)`, in a group inside it, or in the body of a function it calls,
        has a stage whose output holds a full scan and a later stage that is a text filter."""
        for pipeline in self._stages(a, b):
            scanned = False
            for sa, sb in pipeline:
                if scanned and self.filters(sa, sb, args):
                    return True
                scanned = scanned or self.emits(sa, sb, seen, args)
            for sa, sb in pipeline:
                if self._defines(sa, sb):
                    continue  # judged where it is called
                if any(
                    self.filtered(ga, gb, seen, args) for ga, gb in self._groups(sa, sb)
                ):
                    return True
                variants = (
                    [] if self._compound(sa, sb) else self._variants(sa, sb, args)
                )
                for name, call_args in self._called(variants, seen):
                    if self.filtered(*self.functions[name], seen | {name}, call_args):
                        return True
        return False


def _loops(masked: str, raw: str) -> dict[str, list[str]]:
    """`for x in a b c` loops whose list is literal, by variable."""
    out: dict[str, list[str]] = {}
    for m in _LOOP.finditer(masked):
        items = _words(raw[m.start(2) : m.end(2)])
        if items and not any(_UNREAD.search(w) for w in items):
            out[m.group(1)] = items
    return out


def filtered_full_scan(cmd: str, inside: bool = False, depth: int = 0) -> bool:
    """`cmd`, or a shell text it runs, pipes a full luxarch scan into a text filter."""
    try:
        texts = executable_texts(cmd)
        # loops and assignments of the enclosing texts reach the texts nested in them
        loops: dict[str, list[str]] = {}
        for text in texts:
            loops.update(_loops(command_text(text), text))
        values = {k: v for sc in simple_commands(cmd) for k, v in sc.env}
        for text in texts:
            t = _Text(text, inside, depth, loops, values)
            if t.filtered(0, len(t.masked)):
                return True
        return any(
            filtered_full_scan(body, inside or in_container, depth + 1)
            for sc in simple_commands(cmd)
            for body, in_container in _shell_bodies(_command(list(sc.argv)), sc.raw)
        )
    except _TooDeep:
        return True  # a hook that stops reading at some depth would pass everything below it


def main() -> int:
    ev = load_event()
    if ev.get("tool_name") != "Bash":
        return 0
    cmd = text_field(tool_input(ev), "command")
    if filtered_full_scan(cmd):
        sys.stderr.write(
            "DENIED: a full luxarch scan filtered through grep, head or tail runs every rule "
            "to read one.\n"
            "Run only what you need: `luxarch --rule <id>` (exact or substring, repeatable or "
            "comma-separated) runs only the matching rules, and `--path <file>` narrows the output "
            "to one file. The whole repo's per-rule counts are in `.luxarch-status.json` "
            "(`make status`). A full scan you want to read whole runs without a filter.\n"
        )
        return 2
    return 0


sys.exit(guarded(main, "targeted-guard-run"))
